-- LUME · seguridad · identidad: perfiles, roles adicionales, usuarios, segundo factor, parámetros y sesiones.
-- Portado de digsa-java (develop @ 1ff82de): V1__identidad_y_bitacora, V5__sesion_bloqueo_y_clave_inicial, V8__ajustes_revision_s2,
-- V30__parametros_seguridad y V31__roles_adicionales. Se conservan nombres de tablas y columnas para la paridad (ADR-005).
-- Diferencias con el monolito, cada una justificada en su línea:
--   * usuarios.id es GENERATED BY DEFAULT (no ALWAYS): la migración de datos (I9) inserta los mismos id del monolito (ADR-004).
--   * La sesión única ya no va en usuarios.sesion_huella / sesion_ultimo sino en la tabla «sesiones» (el sid del token, ADR-004).
--   * alcance_punto y alcance_regional no tienen FK: puntos y regionales son de «visitas» y aquí llegan como copia por eventos (ADR-002);
--     la validación es de la aplicación y falla cerrado (D5).
-- Migración de datos (I9): tras insertar los usuarios con sus id, avanzar la identidad:
--   SELECT setval(pg_get_serial_sequence('seguridad.usuarios', 'id'), (SELECT max(id) FROM usuarios));
-- Hora: timestamptz (instantes); la hora de negocio se muestra en America/Bogota.

-- ---------- Perfiles base (ids fijos = reglas/Perfil) y roles adicionales (ids desde 100) ----------
CREATE TABLE perfiles (
    id          smallint PRIMARY KEY,
    nombre      text NOT NULL,
    descripcion text CHECK (char_length(descripcion) <= 200),
    activo      boolean NOT NULL DEFAULT true,
    base_id     smallint REFERENCES perfiles (id) ON DELETE RESTRICT,     -- V31: solo los roles adicionales
    creado_por  text CHECK (char_length(creado_por) <= 60),
    creado      timestamptz,
    -- base_id IS NOT NULL explícito: «IN» con NULL da NULL y un CHECK lo dejaría pasar (revisión BD, A1)
    CONSTRAINT ck_perfiles_base CHECK ((id <= 10 AND base_id IS NULL) OR (id >= 100 AND base_id IS NOT NULL AND base_id IN (2, 5, 6, 7, 8, 9, 10))),
    CONSTRAINT ck_perfiles_nombre CHECK (char_length(nombre) BETWEEN 3 AND 60)
);
-- El nombre se compara sin distinguir mayúsculas (dos altas simultáneas de «Rol A» y «rol a» no pasan las dos)
CREATE UNIQUE INDEX uq_perfiles_nombre_ci ON perfiles (lower(nombre));
CREATE INDEX ix_perfiles_base ON perfiles (base_id) WHERE base_id IS NOT NULL;

CREATE SEQUENCE perfiles_adicionales_id_seq AS smallint START WITH 100 MINVALUE 100 MAXVALUE 32000;

