    (3, 'Auditor', 'Sus visitas (líder u otro auditor): su parte del checklist; el líder, 5W2H, acta y envío', true),
    (4, 'Consulta', 'Reemplazado por DIGSA, Sanidad y ESM (decisión 20)', false),
