-- Pantallas de cada rol adicional: el nombre de la constante de reglas/Pantallas (p. ej. RIESGO)
CREATE TABLE perfiles_pantallas (
    perfil_id smallint NOT NULL REFERENCES perfiles (id) ON DELETE RESTRICT,
    pantalla  text NOT NULL CHECK (pantalla ~ '^[A-Z_]{2,40}$'),
    PRIMARY KEY (perfil_id, pantalla)
);

-- ---------- Usuarios ----------
CREATE TABLE usuarios (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre             text NOT NULL CHECK (char_length(nombre) BETWEEN 3 AND 150),
    documento          text CHECK (char_length(documento) <= 30),
    telefono           text CHECK (char_length(telefono) <= 30),
    usuario            text NOT NULL UNIQUE CHECK (usuario ~ '^[a-z0-9._-]{3,50}$'),
    correo             text NOT NULL UNIQUE CHECK (correo = lower(correo) AND char_length(correo) <= 150),
    clave_hash         text NOT NULL,                      -- BCrypt 12; los usuarios nuevos reciben una aleatoria que nadie conoce
    activo             boolean NOT NULL DEFAULT true,
    clave_definida     boolean NOT NULL DEFAULT false,     -- false = nunca la ha definido: se le exige al ingresar
    clave_vence        timestamptz,                        -- vencimiento de la contraseña (vigencia en días)
    debe_cambiar_clave boolean NOT NULL DEFAULT false,     -- el administrador exigió el cambio
    clave_actualizada  timestamptz,                        -- invalida las sesiones iniciadas antes
    clave_inicial      boolean NOT NULL DEFAULT false,     -- V5: la asignó el administrador; se cambia al primer ingreso
    token_hash         char(64),                           -- SHA-256 del enlace de un solo uso
    token_vence        timestamptz,
    intentos           smallint NOT NULL DEFAULT 0,
    bloqueado_hasta    timestamptz,
    ultimo_ingreso     timestamptz,
    alcance_fuerza     text CHECK (alcance_fuerza IN ('EJC', 'ARC', 'FAC')),  -- Sanidad: su fuerza (en el monolito, FK a par_fuerzas)
    alcance_punto      bigint,                             -- ESM: su ESM (copia de visitas)
    alcance_regional   bigint,                             -- OPL regional: su regional (copia de visitas)
    creado             timestamptz NOT NULL DEFAULT now(),
    actualizado        timestamptz NOT NULL DEFAULT now()
) WITH (fillfactor = 80);                                  -- V8: muchas actualizaciones por fila (intentos, ingreso)
CREATE UNIQUE INDEX uq_usuarios_token ON usuarios (token_hash) WHERE token_hash IS NOT NULL;

CREATE TABLE usuarios_perfiles (
    usuario_id bigint NOT NULL REFERENCES usuarios (id) ON DELETE RESTRICT,
    perfil_id  smallint NOT NULL REFERENCES perfiles (id) ON DELETE RESTRICT,
    PRIMARY KEY (usuario_id, perfil_id)
);
CREATE INDEX ix_usuarios_perfiles_perfil ON usuarios_perfiles (perfil_id);

-- ---------- Segundo factor: código de 6 dígitos al correo; solo el SHA-256 ----------
CREATE TABLE mfa_codigos (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    usuario_id  bigint NOT NULL REFERENCES usuarios (id) ON DELETE RESTRICT,
    codigo_hash char(64) NOT NULL,
    creado      timestamptz NOT NULL,
    vence       timestamptz NOT NULL,
    intentos    smallint NOT NULL DEFAULT 0,
    usado       timestamptz,
    ip          text CHECK (char_length(ip) <= 45)
);
-- Último código por (creado DESC, id DESC) sin ordenar y conteo de la última hora; la purga va por «vence».
CREATE INDEX ix_mfa_codigos_usuario ON mfa_codigos (usuario_id, creado DESC, id DESC);
CREATE INDEX ix_mfa_codigos_vence ON mfa_codigos (vence);

-- ---------- Parámetros de seguridad que edita el Administrador (V30) ----------
-- Sin fila, la inactividad vale LUME_SESION_MINUTOS (10 por defecto; Anexo 5, 3.2).
CREATE TABLE seg_parametros (
    clave           text PRIMARY KEY CHECK (clave ~ '^[a-z_]{3,40}$'),
    valor           text NOT NULL CHECK (char_length(valor) <= 100),
    actualizado_por text CHECK (char_length(actualizado_por) <= 60),
    actualizado     timestamptz NOT NULL DEFAULT now()
);

-- ---------- Sesiones (reemplaza usuarios.sesion_huella / sesion_ultimo del monolito) ----------
-- Una fila por ingreso completo; su id es el claim «sid» del token (ADR-004). El gateway consulta su estado en cada petición (caché ≤30 s)
-- e informa la actividad como máximo cada 30 s. «Una sola sesión activa por usuario» la garantiza el índice único parcial.
CREATE TABLE sesiones (
    id          uuid PRIMARY KEY,
    usuario_id  bigint NOT NULL REFERENCES usuarios (id) ON DELETE RESTRICT,
    inicio      timestamptz NOT NULL,
    ultimo      timestamptz NOT NULL,                       -- última actividad conocida (la informa el gateway)
    cerrada     timestamptz,
    motivo      text CHECK (motivo IN ('salida', 'inactividad', 'inactivo', 'clave', 'cerrada', 'reemplazada', 'clave_vencida',
                                       'cambio_clave', 'bloqueado')),
    ip          text CHECK (char_length(ip) <= 45),
    CONSTRAINT ck_sesiones_cierre CHECK ((cerrada IS NULL) = (motivo IS NULL))
) WITH (fillfactor = 85);                                 -- «ultimo» cambia cada 30 s y no está indexado: actualizaciones HOT
CREATE UNIQUE INDEX uq_sesiones_abierta ON sesiones (usuario_id) WHERE cerrada IS NULL;
CREATE INDEX ix_sesiones_usuario_inicio ON sesiones (usuario_id, inicio DESC);

-- ---------- Permisos del rol de la aplicación (D8: el esquema es de seguridad_ddl; la aplicación solo tiene lo que se le concede) ----------
-- Como el monolito (V2, V8, V30, V31): sin DELETE en usuarios ni en perfiles; los perfiles solo se renombran o se activan/inactivan.
GRANT SELECT, INSERT, UPDATE ON usuarios TO ${rol_app};
GRANT USAGE ON SEQUENCE usuarios_id_seq TO ${rol_app};
GRANT SELECT, INSERT ON perfiles TO ${rol_app};
GRANT UPDATE (nombre, descripcion, activo) ON perfiles TO ${rol_app};
GRANT USAGE ON SEQUENCE perfiles_adicionales_id_seq TO ${rol_app};
GRANT SELECT, INSERT, DELETE ON perfiles_pantallas TO ${rol_app};
GRANT SELECT, INSERT, DELETE ON usuarios_perfiles TO ${rol_app};
GRANT SELECT, INSERT, UPDATE, DELETE ON mfa_codigos TO ${rol_app};          -- DELETE: purga de códigos vencidos
GRANT USAGE ON SEQUENCE mfa_codigos_id_seq TO ${rol_app};
GRANT SELECT, INSERT, UPDATE ON seg_parametros TO ${rol_app};
GRANT SELECT, INSERT, UPDATE ON sesiones TO ${rol_app};
